    @field_validator("jwt_secret")
    @classmethod
    def validate_jwt_secret(cls, v: str) -> str:
        if len(v) < 32 and "your_jwt_secret" in v:
            raise ValueError("JWT_SECRET must be set in production and at least 32 characters")
        return v

    @field_validator("supported_currencies")
    @classmethod
    def validate_currencies(cls, v: List[str]) -> List[str]:
        valid_currencies = {"EUR", "USD", "GBP", "CHF", "CZK", "HUF", "PLN", "RON", "HRK"}
