class FraudAutoencoder(nn.Module):
    def __init__(self, input_dim: int):
        super(FraudAutoencoder, self).__init__()
        self.encoder = nn.Sequential(
            nn.Linear(input_dim, 128),
            nn.BatchNorm1d(128),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(128, 64),
            nn.BatchNorm1d(64),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(64, 32),
            nn.BatchNorm1d(32),
            nn.ReLU(),
            nn.Dropout(0.1),
            nn.Linear(32, 16),
        )
        self.decoder = nn.Sequential(
            nn.Linear(16, 32),
            nn.ReLU(),
            nn.Dropout(0.1),
            nn.Linear(32, 64),
            nn.BatchNorm1d(64),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(64, 128),
            nn.BatchNorm1d(128),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(128, input_dim),
            nn.Sigmoid(),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        encoded = self.encoder(x)
        decoded = self.decoder(encoded)
        return decoded

@app.function(image=image, gpu="A100", timeout=600)
def train_fraud_model() -> dict:
    np.random.seed(42)
    torch.manual_seed(42)

    n_samples = 10000
    features = ["amount", "user_age", "transaction_count", "geo_risk"]

    data = pd.DataFrame({
        "amount": np.random.lognormal(5, 1, n_samples),
        "user_age": np.clip(np.random.normal(35, 10, n_samples), 18, 100),
        "transaction_count": np.clip(np.random.poisson(5, n_samples), 0, 100),
        "geo_risk": np.random.uniform(0, 1, n_samples),
    })

    anomalies = np.random.choice(n_samples, 100, replace=False)
    data.loc[anomalies, "amount"] *= np.random.uniform(5, 15, len(anomalies))

    scaler = StandardScaler()
    data_scaled = scaler.fit_transform(data)
    joblib.dump(scaler, "/tmp/scaler.joblib")

    X_train, X_test = train_test_split(data_scaled, test_size=0.2, random_state=42)

    train_dataset = TensorDataset(torch.FloatTensor(X_train))
    train_loader = DataLoader(train_dataset, batch_size=32, shuffle=True, num_workers=0)

    input_dim = X_train.shape[1]
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    model = FraudAutoencoder(input_dim).to(device)
    criterion = nn.MSELoss()
    optimizer = torch.optim.Adam(model.parameters(), lr=0.001, weight_decay=1e-5)
    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=50)

    epochs = 50
    best_loss = float("inf")
    patience = 5
    patience_counter = 0

    for epoch in range(epochs):
        model.train()
        total_loss = 0
        batch_count = 0

        for batch in train_loader:
            inputs = batch[0].to(device)
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, inputs)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
            optimizer.step()
            total_loss += loss.item()
            batch_count += 1

        avg_loss = total_loss / batch_count
        scheduler.step()

        if epoch % 10 == 0:
            logger.info(f"Epoch {epoch}/{epochs}, Loss: {avg_loss:.6f}")

        if avg_loss < best_loss:
            best_loss = avg_loss
            patience_counter = 0
            torch.save(model.state_dict(), "/tmp/fraud_model.pth")
        else:
            patience_counter += 1
            if patience_counter >= patience:
                logger.info(f"Early stopping at epoch {epoch}")
                break

    return {
        "status": "success",
        "epochs_trained": epoch + 1,
        "final_loss": avg_loss,
        "timestamp": datetime.now().isoformat(),
    }

@app.function(image=image, gpu="A100")
def detect_fraud(data: pd.DataFrame) -> pd.DataFrame:
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    scaler = joblib.load("/tmp/scaler.joblib")
    data_scaled = scaler.transform(data)

    input_dim = data_scaled.shape[1]
    model = FraudAutoencoder(input_dim).to(device)
    model.load_state_dict(torch.load("/tmp/fraud_model.pth", map_location=device))
    model.eval()

    with torch.no_grad():
        inputs = torch.FloatTensor(data_scaled).to(device)
        outputs = model(inputs)
        mse = torch.mean((inputs - outputs) ** 2, dim=1)

    threshold = 0.1
    data_copy = data.copy()
    data_copy["fraud_score"] = mse.cpu().numpy()
    data_copy["is_fraud"] = (mse > threshold).cpu().numpy()

    return data_copy[data_copy["is_fraud"]]

