) -> Dict[str, Any]:
    with tracer.start_as_current_span("create_payout") as span:
        try:
            span.set_attribute("user_id", user["user_id"])
            span.set_attribute("amount", request.amount)
            span.set_attribute("currency", request.currency)

            payout_id = str(uuid.uuid4())
            timestamp = datetime.now(timezone.utc)

            task = celery.send_task(
                "tasks.process_payout",
                args=[user["user_id"], request.amount, request.currency, None],
                countdown=0,
            )

            kafka_msg = {
                "payout_id": payout_id,
                "user_id": user["user_id"],
                "amount": request.amount,
                "currency": request.currency,
                "status": "pending",
                "timestamp": timestamp.isoformat(),
            }
            kafka_producer.send(settings.kafka_topic_fraud, value=kafka_msg)

            logger.info(f"Payout {payout_id} created for user {user['user_id']}")

            return {
                "payout_id": payout_id,
                "status": "pending",
                "amount": request.amount,
                "currency": request.currency,
                "task_id": task.id,
                "created_at": timestamp.isoformat(),
            }

        except Exception as e:
            logger.error(f"Payout creation failed: {str(e)}", exc_info=True)
            sentry_sdk.capture_exception(e)
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail="Payout creation failed",
            )

@app.post("/api/v1/tokenize-card", status_code=status.HTTP_201_CREATED)
async def tokenize_card(
    request: CardTokenRequest,
    user: Dict[str, Any] = Depends(get_current_user),
) -> Dict[str, Any]:
    with tracer.start_as_current_span("tokenize_card") as span:
        try:
            span.set_attribute("user_id", user["user_id"])

            token_data = {
                "card_number": request.card_number[-4:],
                "cardholder": request.cardholder,
                "expiry": request.expiry,
                "timestamp": datetime.now(timezone.utc).isoformat(),
            }

            token_hash = hashlib.sha256(
                json.dumps(token_data).encode() + secrets.token_bytes(32)
            ).hexdigest()

            return {
                "card_token": token_hash,
                "last_four": request.card_number[-4:],
                "expires_in": 86400,
            }

        except Exception as e:
            logger.error(f"Card tokenization failed: {str(e)}", exc_info=True)
            sentry_sdk.capture_exception(e)
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail="Card tokenization failed",
            )

